# Verify that no archive songs remain in any original playlist
archive_set = set(archive_song_ids)
remaining = []
for pl in all_playlists:
    pl_id = pl['playlist_id']
    pl_data = apis.spotify.show_playlist(playlist_id=pl_id, access_token=access_token)
    pl_song_ids = [s['id'] for s in pl_data['songs']]
    overlap = archive_set.intersection(pl_song_ids)
    if overlap:
        remaining.append((pl_id, pl_data['title'], sorted(overlap)))
if remaining:
    print("WARNING: Archive songs still present in some playlists:")
    for pl_id, title, ids in remaining:
        print(f"  Playlist {pl_id} ({title}): {ids}")
else:
    print("All archive songs successfully removed from all original playlists.")
